// Validated JS BigInt reimplementation of the frozen program's bech32 arithmetic.
// All arithmetic in BigInt so Python's arbitrary-precision / negative-int
// bitwise semantics (infinite two's complement, arithmetic >>) are reproduced.
const GEN = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

export function bech32_polymod(values) {
  let chk = 1n;
  for (const v of values) {
    const top = chk >> 25n;
    chk = ((chk & 0x1ffffffn) << 5n) ^ v;
    for (let i = 0n; i < 5n; i++) {
      if ((top >> i) & 1n) chk ^= GEN[Number(i)];
    }
  }
  return chk;
}

// Python's ord() walks CODE POINTS, so we must too (astral chars are ONE value).
export function bech32_hrp_expand(hrp) {
  const cps = [];
  for (const ch of hrp) cps.push(BigInt(ch.codePointAt(0)));
  return [...cps.map((c) => c >> 5n), 0n, ...cps.map((c) => c & 31n)];
}

export function bech32_verify_checksum(hrp, data) {
  return bech32_polymod([...bech32_hrp_expand(hrp), ...data]) === 1n;
}

export function bech32_create_checksum(hrp, data) {
  const polymod =
    bech32_polymod([...bech32_hrp_expand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n]) ^ 1n;
  const out = [];
  for (let i = 0n; i < 6n; i++) out.push((polymod >> (5n * (5n - i))) & 31n);
  return out;
}
