import { execFile } from 'node:child_process';
import { bech32_create_checksum, bech32_verify_checksum } from './bech32.mjs';
const EXE = '/workspace/dataset/test10_executable';

function run(hrp, bStr) {
  return new Promise((res) => {
    execFile(EXE, [`--a=${hrp}`, `--b=${bStr}`], { encoding: 'utf8', maxBuffer: 1 << 28 },
      (err, stdout, stderr) => res({ code: err ? (err.code ?? 1) : 0, stdout, stderr }));
  });
}

// Model the whole program's stdout for the success path.
function model(hrp, bStr) {
  const data = bStr.split(',').map((s) => BigInt(s.trim()));
  const cs = bech32_create_checksum(hrp, data);
  const ok = bech32_verify_checksum(hrp, [...data, ...cs]);
  return `[${cs.map(String).join(', ')}]\n${ok ? 'True' : 'False'}\n`;
}

let n = 0, bad = [], falses = [];
async function check(hrp, bStr, label) {
  n++;
  const got = await run(hrp, bStr);
  let exp;
  try { exp = model(hrp, bStr); } catch (e) { exp = `MODEL-THREW:${e.message}`; }
  if (got.stdout !== exp || got.code !== 0 || got.stderr !== '') {
    bad.push({ label, hrp, bStr, gotOut: got.stdout, gotErr: got.stderr.slice(0, 300), code: got.code, exp });
  }
  if (/^False$/m.test(got.stdout)) falses.push({ label, hrp, bStr, out: got.stdout });
  return got;
}
export { check, run, model };
export function report() {
  console.log(`CASES=${n} MISMATCHES=${bad.length} FALSE_SECOND_LINE=${falses.length}`);
  for (const b of bad.slice(0, 25)) console.log('MISMATCH ' + JSON.stringify(b));
  for (const f of falses.slice(0, 25)) console.log('FALSE ' + JSON.stringify(f));
}
