import { check, report } from './diff.mjs';

// deterministic PRNG so runs are reproducible
let s = 0x2f6e2b1n;
const rnd = () => {
  s = (s * 6364136223846793005n + 1442695040888963407n) & ((1n << 64n) - 1n);
  return Number((s >> 33n) & 0xffffffffn) / 0x100000000;
};
const ri = (n) => Math.floor(rnd() * n);

const CP_POOL = [
  ...'abcdefghijklmnopqrstuvwxyz'.split(''),
  ...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split(''),
  ...'0123456789'.split(''),
  ...'!@#$%^&*()-_=+[]{};:,.<>/?|~`'.split(''),
  ' ', '\t', '\x01', '\x0b', '\x1f', '\x7f',
  'é', 'ü', 'ñ', 'ß', 'ø', 'Ω', 'λ', 'ж', 'א', 'ع',
  '中', '文', '日', '本', 'ह', 'ก',
  '\u{1F600}', '\u{1F4A9}', '\u{1F680}', '\u{10FFFF}', '\u{10000}', '\u{2070E}',
  ' ', '​', '﻿', '￿', '', '߿', 'ࠀ',
];

const randHrp = () => {
  const n = ri(25);
  let out = '';
  for (let i = 0; i < n; i++) out += CP_POOL[ri(CP_POOL.length)];
  return out;
};

const randVal = () => {
  const k = ri(12);
  let v;
  if (k < 4) v = BigInt(ri(32));                      // in-range 5-bit
  else if (k === 4) v = BigInt(ri(256));
  else if (k === 5) v = BigInt(ri(1 << 30));
  else if (k === 6) v = (1n << BigInt(ri(80))) + BigInt(ri(1000));
  else if (k === 7) v = BigInt('9' .repeat(1 + ri(40)));
  else if (k === 8) v = -BigInt(ri(1 << 20));
  else if (k === 9) v = -(1n << BigInt(ri(70)));
  else if (k === 10) v = -BigInt('1234567890'.repeat(1 + ri(4)));
  else v = BigInt(ri(4294967296));
  return v;
};

const randData = () => {
  const n = 1 + ri(12);
  const a = [];
  for (let i = 0; i < n; i++) a.push(randVal().toString());
  return a.join(',');
};

const run = async () => {
  for (let i = 0; i < 240; i++) await check(randHrp(), randData(), `rand${i}`);

  // long data lists
  for (const len of [500, 501, 777, 1000, 2000]) {
    const a = [];
    for (let i = 0; i < len; i++) a.push(String(ri(32)));
    await check('bc', a.join(','), `long-inrange-${len}`);
    const b = [];
    for (let i = 0; i < len; i++) b.push(randVal().toString());
    await check('a\u{1F600}z', b.join(','), `long-wild-${len}`);
  }

  // long hrp x long data
  await check('x'.repeat(200), Array.from({ length: 600 }, (_, i) => String(i % 32)).join(','), 'long200x600');
  await check('é中\u{1F600}'.repeat(40), Array.from({ length: 500 }, () => String(ri(1 << 30))).join(','), 'longuni x500');

  report();
};
run();

// Sensitivity check: do WRONG models actually diverge on my probe set?
// If a mutant passes everything, my probes prove nothing.
import { execFile } from 'node:child_process';
const EXE = '/workspace/dataset/test10_executable';
const run = (hrp, b) => new Promise((res) => execFile(EXE, [`--a=${hrp}`, `--b=${b}`],
  { encoding: 'utf8', maxBuffer: 1 << 28 }, (e, so) => res(so)));

const GOOD = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

function mk({ gen = GOOD, utf16 = false, noMask = false, lower = false, revChk = false }) {
  const polymod = (vals) => {
    let chk = 1n;
    for (const v of vals) {
      const top = chk >> 25n;
      chk = ((chk & (noMask ? 0x3ffffffn : 0x1ffffffn)) << 5n) ^ v;
      for (let i = 0n; i < 5n; i++) if ((top >> i) & 1n) chk ^= gen[Number(i)];
    }
    return chk;
  };
  const expand = (h) => {
    if (lower) h = h.toLowerCase();
    const cps = [];
    if (utf16) { for (let i = 0; i < h.length; i++) cps.push(BigInt(h.charCodeAt(i))); }
    else { for (const c of h) cps.push(BigInt(c.codePointAt(0))); }
    return [...cps.map((c) => c >> 5n), 0n, ...cps.map((c) => c & 31n)];
  };
  return (hrp, data) => {
    const p = polymod([...expand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n]) ^ 1n;
    const out = [];
    for (let i = 0n; i < 6n; i++) out.push((p >> (5n * (5n - i))) & 31n);
    if (revChk) out.reverse();
    return `[${out.map(String).join(', ')}]`;
  };
}

const badGen = GOOD.slice(); badGen[2] ^= 1n;          // one bit flipped in GEN[2]
const swapGen = [GOOD[1], GOOD[0], GOOD[2], GOOD[3], GOOD[4]];

const MUTANTS = {
  'correct            ': mk({}),
  'utf16-code-units   ': mk({ utf16: true }),
  'GEN[2] 1-bit-flip  ': mk({ gen: badGen }),
  'GEN[0]<->GEN[1] swap': mk({ gen: swapGen }),
  'mask 0x3ffffff     ': mk({ noMask: true }),
  'hrp lowercased     ': mk({ lower: true }),
  'checksum reversed  ': mk({ revChk: true }),
};

const CASES = [
  ['bc', '0,1,2'], ['', '0'], ['BC', '0,1,2'], ['\u{1F600}', '0,1,2'],
  ['a\u{1F600}b', '5,7'], ['é中', '31,0,17'], ['abc', '-1,-2'],
  ['x'.repeat(90), '18446744073709551616,3'], ['Mixed', '1073741823'],
  ['a b', '32,33,255'],
];

const main = async () => {
  const tally = {};
  for (const name of Object.keys(MUTANTS)) tally[name] = { fail: 0, firstFail: null };
  for (const [h, b] of CASES) {
    const real = (await run(h, b)).split('\n')[0];
    for (const [name, f] of Object.entries(MUTANTS)) {
      const got = f(h, b.split(',').map(BigInt));
      if (got !== real) {
        tally[name].fail++;
        if (!tally[name].firstFail) tally[name].firstFail = `hrp=${JSON.stringify(h)} b=${b} real=${real} mutant=${got}`;
      }
    }
  }
  for (const [name, t] of Object.entries(tally))
    console.log(`${name} fails ${t.fail}/${CASES.length}  ${t.firstFail ?? ''}`);
};
main();

// (a) Does the 0x1ffffff-vs-0x3ffffff mask ambiguity show up on LINE 2?
// (b) Exhaustive hunt for a second line that is not "True".
import { execFile } from 'node:child_process';
const EXE = '/workspace/dataset/test10_executable';
const run = (hrp, b) => new Promise((res) => execFile(EXE, [`--a=${hrp}`, `--b=${b}`],
  { encoding: 'utf8', maxBuffer: 1 << 28 }, (e, so, se) => res({ so, se, code: e ? (e.code ?? 1) : 0 })));
const GEN = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

function build(mask) {
  const polymod = (vals) => {
    let chk = 1n;
    for (const v of vals) {
      const top = chk >> 25n;
      chk = ((chk & mask) << 5n) ^ v;
      for (let i = 0n; i < 5n; i++) if ((top >> i) & 1n) chk ^= GEN[Number(i)];
    }
    return chk;
  };
  const expand = (h) => {
    const cps = [];
    for (const c of h) cps.push(BigInt(c.codePointAt(0)));
    return [...cps.map((c) => c >> 5n), 0n, ...cps.map((c) => c & 31n)];
  };
  return (hrp, data) => {
    const p = polymod([...expand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n]) ^ 1n;
    const cs = [];
    for (let i = 0n; i < 6n; i++) cs.push((p >> (5n * (5n - i))) & 31n);
    const ok = polymod([...expand(hrp), ...data, ...cs]) === 1n;
    return `[${cs.map(String).join(', ')}]\n${ok ? 'True' : 'False'}\n`;
  };
}
const m25 = build(0x1ffffffn), m26 = build(0x3ffffffn);

let s = 991n;
const rnd = () => { s = (s * 6364136223846793005n + 1442695040888963407n) & ((1n << 64n) - 1n); return Number((s >> 33n) & 0xffffffffn) / 0x100000000; };
const ri = (n) => Math.floor(rnd() * n);

const main = async () => {
  let n = 0, diff25 = 0, diff26 = 0, falses = [], firstMaskSplit = null;
  const cases = [];
  // adversarial / False-hunting inputs
  for (let i = 0; i < 120; i++) cases.push(['abcdefgh'.slice(0, 1 + ri(8)), Array.from({ length: 1 + ri(8) }, () => String(ri(1 << 30))).join(',')]);
  for (let i = 0; i < 40; i++) cases.push(['', Array.from({ length: 1 + ri(6) }, () => (-(1n << BigInt(ri(90)))).toString()).join(',')]);
  for (let i = 0; i < 40; i++) cases.push(['\u{1F600}é', Array.from({ length: 1 + ri(6) }, () => ((1n << BigInt(ri(120))) - 1n).toString()).join(',')]);
  // extremes designed to set high bits / bit-25 of state
  for (const v of ['1073741823', '1073741824', '2147483647', '-1', '-1073741824', '536870912', '33554431', '33554432']) {
    for (const h of ['', 'a', 'bc', '\u{1F600}', 'Z'.repeat(90)]) cases.push([h, v]);
    cases.push(['bc', `${v},${v},${v},${v},${v},${v},${v}`]);
  }
  for (const [h, b] of cases) {
    n++;
    const r = await run(h, b);
    const data = b.split(',').map(BigInt);
    const a = m25(h, data), c = m26(h, data);
    if (r.so !== a) diff25++;
    if (r.so !== c) { diff26++; if (!firstMaskSplit) firstMaskSplit = `hrp=${JSON.stringify(h)} b=${b}\n   real=${JSON.stringify(r.so)}\n   mask26=${JSON.stringify(c)}`; }
    if (/False/.test(r.so)) falses.push([h, b, r.so]);
  }
  console.log(`FALSE-HUNT cases=${n}`);
  console.log(`  mask 0x1ffffff mismatches = ${diff25}`);
  console.log(`  mask 0x3ffffff mismatches = ${diff26}`);
  if (firstMaskSplit) console.log('  first mask-26 divergence:\n   ' + firstMaskSplit);
  console.log(`  second-line "False" found = ${falses.length}`);
  for (const f of falses.slice(0, 5)) console.log('   ' + JSON.stringify(f));
};
main();

// Structural proof of hrp_expand WITHOUT assuming it.
// expand('') == [0]. For an hrp whose code points are all < 32, expand(H) starts
// with a run of zeros, so expand(H)+D can be re-created as expand('')+E.
//   H = chr(c) (c<32)  => expand(H) = [c>>5, 0, c&31] = [0, 0, c]
//   so run(H, D) must equal run('', [0, c, ...D])
// Any deviation in the separator-0 / ordering / >>5 / &31 shape breaks this.
import { execFile } from 'node:child_process';
const EXE = '/workspace/dataset/test10_executable';
const run = (hrp, b) => new Promise((res) => execFile(EXE, [`--a=${hrp}`, `--b=${b}`],
  { encoding: 'utf8', maxBuffer: 1 << 26 }, (e, so, se) => res({ so, se, code: e ? (e.code ?? 1) : 0 })));

const main = async () => {
  let n = 0, ok = 0, bad = [];
  const D = ['5,7', '0', '31,31,31', '-1,1000000', '3'];

  // --- 1-char control hrp vs data-emulation ---
  for (const c of [1, 2, 7, 9, 11, 12, 13, 27, 30, 31]) {
    for (const d of D) {
      n++;
      const a = await run(String.fromCodePoint(c), d);
      const b = await run('', `0,${c},${d}`);
      if (a.so === b.so) ok++; else bad.push({ kind: '1char', c, d, a: a.so, b: b.so });
    }
  }
  // --- 2-char control hrp: expand = [0,0,0,c1,c2] -> run('', [0,0,c1,c2,...D]) ---
  for (const [c1, c2] of [[1, 2], [31, 1], [9, 13], [30, 30]]) {
    for (const d of D) {
      n++;
      const a = await run(String.fromCodePoint(c1) + String.fromCodePoint(c2), d);
      const b = await run('', `0,0,${c1},${c2},${d}`);
      if (a.so === b.so) ok++; else bad.push({ kind: '2char', c1, c2, d, a: a.so, b: b.so });
    }
  }
  // --- 3-char control hrp: expand = [0,0,0,0,c1,c2,c3] ---
  for (const [c1, c2, c3] of [[1, 2, 3], [31, 0 + 1, 30]]) {
    for (const d of D) {
      n++;
      const a = await run([c1, c2, c3].map((x) => String.fromCodePoint(x)).join(''), d);
      const b = await run('', `0,0,0,${c1},${c2},${c3},${d}`);
      if (a.so === b.so) ok++; else bad.push({ kind: '3char', c1, c2, c3, d, a: a.so, b: b.so });
    }
  }
  // --- NEGATIVE control: the WRONG shapes must NOT match (proves the test bites) ---
  const neg = [];
  for (const c of [7, 27]) {
    // no separator 0
    let a = await run(String.fromCodePoint(c), '5,7');
    let b = await run('', `${c},5,7`);            // missing the [0] separator
    neg.push(['no-separator', a.so === b.so]);
    b = await run('', `0,${c},0,5,7`);            // extra element
    neg.push(['extra-elem', a.so === b.so]);
    b = await run('', `${c},0,5,7`);              // swapped order
    neg.push(['swapped', a.so === b.so]);
  }
  console.log(`EXPAND-STRUCTURE: cases=${n} matched=${ok} failed=${bad.length}`);
  for (const x of bad.slice(0, 6)) console.log('  FAIL ' + JSON.stringify(x));
  console.log('  negative controls (must all be false): ' + JSON.stringify(neg));
};
main();

// Direct black-box readout of ord() for arbitrary characters.
// expand('\x01' + X) = [1>>5, ord(X)>>5, 0, 1&31, ord(X)&31] = [0, ord(X)>>5, 0, 1, ord(X)&31]
// and expand('') = [0], so:
//     run('\x01'+X, D)  ==  run('', [ord(X)>>5, 0, 1, ord(X)&31] + D)
// We SOLVE for ord(X) by testing candidate hypotheses, rather than assuming one.
import { execFile } from 'node:child_process';
const EXE = '/workspace/dataset/test10_executable';
const run = (hrp, b) => new Promise((res) => execFile(EXE, [`--a=${hrp}`, `--b=${b}`],
  { encoding: 'utf8', maxBuffer: 1 << 26 }, (e, so) => res(so)));

const D = '5,7,9';
const emu = (cps) => run('', `${cps.map((c) => `${c >> 5},`).join('')}0,1,${cps.map((c) => c & 31).join(',')},${D}`);

const CHARS = ['a', 'Z', '0', '~', ' ', 'é', 'ü', '中', '\u{1F600}', '\u{1F4A9}', '\u{10FFFF}', '\u{10000}'];

const main = async () => {
  console.log('char            codepoint  utf16-units        verdict');
  for (const X of CHARS) {
    const real = await run('\x01' + X, D);
    const cp = X.codePointAt(0);
    const units = [];
    for (let i = 0; i < X.length; i++) units.push(X.charCodeAt(i));
    const byCodePoint = await emu([cp]);
    const byUtf16 = await emu(units);
    // also a UTF-8 byte hypothesis, for completeness
    const bytes = [...Buffer.from(X, 'utf8')];
    const byUtf8 = await emu(bytes);
    const verdict = [
      byCodePoint === real ? 'CODEPOINT-MATCH' : null,
      byUtf16 === real && units.length !== 1 ? 'utf16-match' : null,
      byUtf8 === real && bytes.length !== 1 ? 'utf8-bytes-match' : null,
    ].filter(Boolean).join(' + ') || 'NO MODEL MATCHED';
    console.log(
      `${JSON.stringify(X).padEnd(14)} ${String(cp).padStart(9)}  ${JSON.stringify(units).padEnd(18)} ${verdict}`
    );
  }
};
main();
